{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vendor SLA Data",
    "url": "http://localhost:7804",
    "widgets_json": {
      "sla_newsfeed": {
        "name": "Vendor Notices",
        "description": "Vendor incident notices feed.",
        "endpoint": "/vendor-notices",
        "type": "newsfeed",
        "params": [
          {
            "paramName": "vendor",
            "type": "text",
            "label": "Vendor",
            "value": "AlphaFeed",
            "description": "Vendor filter for notices."
          }
        ],
        "w": 20,
        "h": 12,
        "staleTime": 900000
      },
      "breach_metric": {
        "name": "Open Breaches",
        "description": "Count of open SLA breaches.",
        "endpoint": "/breach-count",
        "type": "metric",
        "w": 8,
        "h": 5,
        "staleTime": 900000
      },
      "vendor_sla_table": {
        "name": "Vendor SLA Status",
        "description": "Vendor SLA state with breach flags.",
        "endpoint": "/vendor-sla",
        "type": "table",
        "params": [
          {
            "paramName": "status",
            "type": "text",
            "label": "Status",
            "value": "Open",
            "options": [
              "Open",
              "Escalated",
              "Resolved"
            ],
            "description": "Status filter for SLA data."
          }
        ],
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "data": {
          "columnsDefs": [
            {
              "field": "vendor",
              "headerName": "Vendor",
              "cellDataType": "text"
            },
            {
              "field": "status",
              "headerName": "Status",
              "cellDataType": "text",
              "renderFn": "titleCase"
            },
            {
              "field": "latency_ms",
              "headerName": "Latency (ms)",
              "cellDataType": "number"
            },
            {
              "field": "breach",
              "headerName": "Breach",
              "cellDataType": "boolean"
            }
          ]
        }
      }
    },
    "apps_json": [
      {
        "name": "Vendor Notice Room",
        "description": "Vendor notices and breach count.",
        "tabs": {
          "notices": {
            "id": "notices",
            "name": "Notices",
            "layout": [
              {
                "i": "sla_newsfeed",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 12
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "breach_metric",
                "x": 0,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          }
        }
      }
    ]
  }
}

